# AI: below section was generated by an AI
# Adds -DKITE_FW_VERSION="<semver>+<short commit>.<environment>" at build time.
# Without a git commit (for example a git archive build), set KITE_FW_COMMIT to the 7-40 digit
# lowercase hex commit; otherwise the commit is "unknown".
# Adds -DKITE_BUILD_EPOCH=<seconds>, the certificate clock floor: SOURCE_DATE_EPOCH, else the commit
# time, else 0 (the firmware then keeps its fixed 2026-01-01 floor). The build time itself is never used.
import os
import re
import subprocess
import sys
import time

Import("env")  # noqa: F821 (provided by PlatformIO)

project = env.subst("$PROJECT_DIR")  # noqa: F821
with open(os.path.join(project, "VERSION"), encoding="ascii") as f:
    semver = f.read().strip()


def git(*args):
    return subprocess.check_output(["git", *args], cwd=project, stderr=subprocess.DEVNULL).decode().strip()


same = False
try:
    # Only this checkout's own commit counts, not one of an enclosing repository.
    same = os.path.realpath(git("rev-parse", "--show-toplevel")) == os.path.realpath(project)
    commit = git("rev-parse", "--short=7", "HEAD") if same else "unknown"
except Exception:
    commit = "unknown"
if commit == "unknown" and os.environ.get("KITE_FW_COMMIT"):
    commit = os.environ["KITE_FW_COMMIT"]

epoch = os.environ.get("SOURCE_DATE_EPOCH", "")
if not epoch and same:
    try:
        epoch = git("log", "-1", "--format=%ct", "HEAD")
    except Exception:
        epoch = ""
# A future source date would keep the device from accepting the real clock; one day covers clock skew.
if epoch and (not re.fullmatch(r"[0-9]{1,10}", epoch) or int(epoch) > 0xFFFFFFFF or int(epoch) > time.time() + 86400):
    sys.stderr.write(f"kite_version: invalid build epoch {epoch!r} (SOURCE_DATE_EPOCH or commit time)\n")
    env.Exit(1)  # noqa: F821
epoch = int(epoch) if epoch else 0
version = f"{semver}+{commit}.{env['PIOENV']}"  # noqa: F821

# Same rule as KiteWindHttp::validVersion(), so the device never refuses its own build.
if (not re.fullmatch(r"\d+\.\d+\.\d+", semver) or not re.fullmatch(r"[0-9a-f]{7,40}|unknown", commit)
        or not re.fullmatch(r"[0-9A-Za-z._+-]{1,64}", version)):
    sys.stderr.write(f"kite_version: invalid firmware version {version!r}\n")
    env.Exit(1)  # noqa: F821
print(f"kite_version: {version}, build epoch {epoch}")
env.Append(CPPDEFINES=[("KITE_FW_VERSION", env.StringifyMacro(version)), ("KITE_BUILD_EPOCH", epoch)])  # noqa: F821
# AI: end
